import { Expense } from "../../types/types";
import { useContext } from "react";
import { AppContext } from "../../context/AppContext";
import ExpenseList from "./ExpenseList";

const context = useContext(AppContext);

//const { expenses, setExpenses } = useContext(AppContext);
  
 //} from "../../context/AppContext";
const ExpenseItem = (currentExpense: Expense) => {
  // Exercise: Consume the AppContext here
  //return <ExpenseItem: idText,name,cost> < /> </ExpenseItem> ;
  //const AppCon = useContext(AppContext);
 

  const handleDeleteExpense = (currentExpense: Expense) => {
    // Exercise: Remove expense from expenses context array

    const updateExpenses = context.expenses.filter(
      (expense) => expense.id !== currentExpense.id
    );
    context.setExpenses(updateExpenses);
  };

    //setExpenses(() =>
      //expenses.filter((expense) => expense.id !== currentExpense.id)

   //);
//};

  return (
    <li className="list-group-item d-flex justify-content-between align-items-center">
      <div>{currentExpense.name}</div>
      <div>${currentExpense.cost}</div>
      <div>
        <button onClick={() => handleDeleteExpense(currentExpense)}>x</button>
      </div>
    </li>
  );
};

export default ExpenseItem;
